/* ============================================================
   Interactive redirection galleries (simulation + hardware).
   Vanilla JS, no build step. Theme-aware via CSS variables.
   ============================================================ */
(function () {
  "use strict";

  /* ----------  models (text labels only)  ---------- */
  const MODELS = {
    pi05:    { name: "π0.5",    cls: "m-pi" },
    smolvla: { name: "SmolVLA", cls: "m-hf" }
  };

  /* ----------  helpers  ---------- */
  function esc(s) {
    return String(s).replace(/[&<>"]/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c];
    });
  }
  function encPath(p) {
    return p.split("/").map(encodeURIComponent).join("/");
  }
  // char-level prefix/suffix diff WITHIN a single word (unicode code points)
  function diffWord(bword, aword) {
    const a = Array.from(bword), b = Array.from(aword);
    const max = Math.min(a.length, b.length);
    let p = 0;
    while (p < max && a[p] === b[p]) p++;
    let s = 0;
    while (s < max - p && a[a.length - 1 - s] === b[b.length - 1 - s]) s++;
    const bMid = a.slice(p, a.length - s).join(""), aMid = b.slice(p, b.length - s).join("");
    const bH = esc(a.slice(0, p).join("")) + (bMid ? '<span class="d-rm">' + esc(bMid) + "</span>" : "") + esc(a.slice(a.length - s).join(""));
    const aH = esc(b.slice(0, p).join("")) +
      (aMid ? '<span class="d-hl">' + esc(aMid) + "</span>" : (bMid ? '<span class="d-caret"></span>' : "")) +
      esc(b.slice(b.length - s).join(""));
    return { bH: bH, aH: aH };
  }
  // word-level LCS -> list of matched [iA, iB] index pairs
  function lcsPairs(A, B) {
    const m = A.length, n = B.length;
    const dp = Array.from({ length: m + 1 }, function () { return new Array(n + 1).fill(0); });
    for (let i = m - 1; i >= 0; i--)
      for (let j = n - 1; j >= 0; j--)
        dp[i][j] = A[i] === B[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1]);
    const pairs = []; let i = 0, j = 0;
    while (i < m && j < n) {
      if (A[i] === B[j]) { pairs.push([i, j]); i++; j++; }
      else if (dp[i + 1][j] >= dp[i][j + 1]) i++; else j++;
    }
    return pairs;
  }
  // word-aware diff: highlight only the changed characters inside each changed word,
  // so multi-region edits don't bridge the unchanged words between them.
  function diffRender(benign, attack) {
    const A = benign.split(" "), B = attack.split(" ");
    const pairs = lcsPairs(A, B); pairs.push([A.length, B.length]);
    const segB = [], segA = []; let i = 0, j = 0;
    for (let p = 0; p < pairs.length; p++) {
      const mi = pairs[p][0], mj = pairs[p][1];
      const bw = A.slice(i, mi), aw = B.slice(j, mj);
      const k = Math.min(bw.length, aw.length);
      for (let x = 0; x < k; x++) { const d = diffWord(bw[x], aw[x]); segB.push(d.bH); segA.push(d.aH); }
      for (let x = k; x < bw.length; x++) segB.push('<span class="d-rm">' + esc(bw[x]) + "</span>");
      for (let x = k; x < aw.length; x++) segA.push('<span class="d-hl">' + esc(aw[x]) + "</span>");
      if (mi < A.length) { segB.push(esc(A[mi])); segA.push(esc(B[mj])); i = mi + 1; j = mj + 1; }
    }
    return { benign: segB.join(" "), attack: segA.join(" ") };
  }
  function lev(s1, s2) {
    const a = Array.from(s1), b = Array.from(s2), m = a.length, n = b.length;
    const d = new Array(n + 1);
    for (let j = 0; j <= n; j++) d[j] = j;
    for (let i = 1; i <= m; i++) {
      let prev = d[0]; d[0] = i;
      for (let j = 1; j <= n; j++) {
        const tmp = d[j];
        d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
        prev = tmp;
      }
    }
    return d[n];
  }
  function videoTag(src) {
    return '<video src="' + encPath(src) + '" muted loop playsinline autoplay preload="metadata" controls></video>';
  }
  function modelTag(m) {
    return '<span class="vg-modeltag ' + m.cls + '">' + esc(m.name) + "</span>";
  }

  /* ----------  render one benign vs adversarial pair  ---------- */
  function renderPair(mount, it) {
    const dr = diffRender(it.benign, it.attack);
    const edits = lev(it.benign, it.attack);
    const m = it.model ? MODELS[it.model] : null;
    mount.innerHTML =
      '<div class="vg-grid">' +
        '<figure class="vg-panel benign">' +
          '<figcaption class="vg-head"><span class="vg-dot"></span>Benign rollout<span class="vg-tag-note">task completes as written</span></figcaption>' +
          '<div class="vg-video">' + videoTag(it.normalVideo) + "</div>" +
          '<div class="vg-prompt">“' + dr.benign + '”</div>' +
        "</figure>" +
        '<div class="vg-mid" aria-hidden="true">' +
          '<div class="vg-edit">Δ ' + edits + " char" + (edits === 1 ? "" : "s") + "</div>" +
          '<svg class="vg-arrow" viewBox="0 0 40 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M2 12h33"/><path d="M28 5l8 7-8 7"/></svg>' +
        "</div>" +
        '<figure class="vg-panel attack">' +
          '<figcaption class="vg-head"><span class="vg-dot"></span>Redirected rollout' +
            (m ? ' <span class="vg-headmodel">' + modelTag(m) + "</span>" : "") +
            '<span class="vg-tag-note">near-benign adversarial prompt</span></figcaption>' +
          '<div class="vg-video">' + videoTag(it.advVideo) + "</div>" +
          '<div class="vg-prompt">“' + dr.attack + '”</div>' +
        "</figure>" +
      "</div>" +
      '<div class="vg-foot">' +
        '<div class="vg-intent">' +
          '<span class="vg-intent-lbl">Attacker’s intended outcome</span>' +
          '<span class="vg-intent-txt">' + esc(it.intention) + "</span>" +
        "</div>" +
        '<div class="vg-meta">' +
          (it.suite ? '<span class="vg-chip">' + esc(it.suite) + "</span>" : "") +
          (it.task ? '<span class="vg-chip">' + esc(it.task) + "</span>" : "") +
        "</div>" +
      "</div>";
    const vids = mount.querySelectorAll("video");
    vids.forEach(function (v) { var pr = v.play(); if (pr && pr.catch) pr.catch(function(){}); });
  }

  /* ----------  dice (no immediate repeat)  ---------- */
  function wireDice(items, mount, btn, counter) {
    if (!mount) return;
    let last = -1;
    function roll() {
      if (!items.length) return;
      let i;
      do { i = Math.floor(Math.random() * items.length); } while (items.length > 1 && i === last);
      last = i;
      renderPair(mount, items[i]);
      if (counter) counter.textContent = (i + 1) + " / " + items.length;
    }
    if (btn) {
      btn.addEventListener("click", function () {
        btn.classList.remove("rolling");
        void btn.offsetWidth;        // restart spin animation
        btn.classList.add("rolling");
        roll();
      });
    }
    roll();
  }

  function init() {
    wireDice(window.SIM_PAIRS || [], document.getElementById("sim-stage"),
             document.getElementById("sim-dice"));
    wireDice(window.HW_DATA || [], document.getElementById("hw-stage"),
             document.getElementById("hw-dice"));
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", init);
  } else {
    init();
  }
})();
